INSERT OR REPLACE INTO docs(col,id,data,updated) VALUES('nguoi','s02','{"ben": "Nhà thầu, hệ thống trong NDC", "dv": "Cổng DVC", "nguoi": [{"can_cu": "Hùng gọi ''sếp D01 - Xuân Quyết (PGD)''; DMDC: Phạm Minh ''anh Quyết là trưởng phòng đại diện bên e''; Le Cuong ''anh A Quyết - Thanh Toán TT - D01''. Chức danh PGĐ hay trưởng phòng [141 tin] | Anh Hùng luôn gắn tên \"D01 - Xuân Quyết (PGD)\" trong nhóm MBFS-NADAT; chọn PGĐ", "ho_ten": "Nguyễn Xuân Quyết", "nguon": "Đối chiếu chat 15/11", "nhom_chat": "[TELE] C12 - C06 SSO - NDOP LHL - DVCQG.PAKN; [TELE] D01-NADAT-VNTDO: Thanh toán SDL; [TELE] DA175- PAKN+PA-SaiKhac; [TELE] MBFS-NADAT Nội bộ; [TELE] NDOP-C12-ThanhToan-VPBank; [TELE] [C12] DVCQG - HTLL - NADAT; [TELE] [MBF-NADAT-C12] Tích hợp Cổng DVC QG; [ZALO] DVCQG vs NHNN", "phong_ban": "D01 (Mobifone/MBFS) – Phó giám đốc, phụ trách Cổng DVCQG", "tai_khoan": "Quyết Nguyễn Xuân (Tele); Nguyễn Xuân Quyết (Zalo); D01 - Xuân Quyết (PGD); MBF.Quyết", "vai_tro": "Lãnh đạo phía D01 phụ trách Cổng DVCQG và Thanh toán tập trung; điều phối PAKN, HTLL, NHNN"}, {"can_cu": "A Quang ''Quyết - @Mr_Tomy D01 gửi giúp Nadat thông tin cụ thể về API''; 05/10 phân công @thamigunbai [14 tin]", "ho_ten": "Mr Tommy (Thành – theo danh sách cũ)", "nguon": "Đối chiếu chat 15/11", "nhom_chat": "[TELE] DVC-NDOP-TTTT # DevTest; [TELE] PAKN-NDOP-DVC # DevTest; [TELE] [MBF-NADAT-C12] Tích hợp Cổng DVC QG", "phong_ban": "D01 – Cổng DVC", "tai_khoan": "Mr Tommy; @Mr_Tomy", "vai_tro": "Đầu mối kỹ thuật Cổng DVCQG, gửi tài liệu tích hợp, phân công dev"}, {"can_cu": "Mr Tommy ''chỗ @thamigunbai phối hợp để tích hợp trên môi trường dev''; Thắng ''e add @oanhchanne QC bên e'' [18 tin] | \"Thắng\" trong nhóm MBF-NADAT-C12 là Thắng BV: Nguyễn Duy Hòa nói \"owner file đấy là của thắng\" khi bàn API Cổng gọi PAKN", "ho_ten": "Thắng BV", "nguon": "Đối chiếu chat 15/11", "nhom_chat": "[TELE] DVC-NDOP-TTTT # DevTest; [TELE] PAKN-NDOP-DVC # DevTest; [TELE] [MBF-NADAT-C12] Tích hợp Cổng DVC QG; [TELE] [MBF-NADAT